  let ahead = frame.forward * cos(nose.x) + banked * sin(nose.x);
  frame.right = banked * cos(nose.x) - frame.forward * sin(nose.x);
  frame.forward = ahead * cos(nose.y) + crown * sin(nose.y);
  frame.up = crown * cos(nose.y) - ahead * sin(nose.y);
