// Integer hashes: a plant must be the same rung on every driver, which fract(sin(x)) does not promise.
fn mix32(v: u32) -> u32 {
  let x = v * 747796405u + 2891336453u;
  let w = ((x >> ((x >> 28u) + 4u)) ^ x) * 277803737u;
  return (w >> 22u) ^ w;
}

fn chance(a: u32, b: u32, c: u32) -> f32 {
  return f32(mix32(a ^ mix32(b ^ mix32(c)))) / 4294967295.0;
}

// ── The tentacle: arcs of constant curvature ──
const NECK: f32 = LENGTH * 0.4;
const ARM: f32 = LENGTH - NECK;
// The half-turn at which slack starts to stow: past a quarter circle each side a bow swells beyond its own ends, by 5 cm here.
const BOW_LIMIT: f32 = 1.9;

fn sinc(x: f32) -> f32 {
  if (abs(x) < 1e-3) { return 1.0 - x * x / 6.0; }
  return sin(x) / x;
}

// The half-turn of an arc whose chord is that share of its length: sinc inverted on [0, π], where it only falls.
fn halfTurn(share: f32) -> f32 {
  var low = 0.0;
  var high = 3.14159265;
  for (var i = 0u; i < 20u; i = i + 1u) {
    let mid = (low + high) * 0.5;
    if (sinc(mid) > share) { low = mid; } else { high = mid; }
  }
  return (low + high) * 0.5;
}

// Where an arc of curvature k has got to after s metres, in its own plane: x along its start, y the way it bends.
fn arcAt(k: f32, s: f32) -> vec2f {
  let a = k * s;
  if (abs(a) < 1e-3) { return vec2f(s * (1.0 - a * a / 6.0), s * a * 0.5); }
  return vec2f(sin(a) / k, (1.0 - cos(a)) / k);
}

fn turned(v: vec2f, angle: f32) -> vec2f {
  return vec2f(v.x * cos(angle) - v.y * sin(angle), v.x * sin(angle) + v.y * cos(angle));
}

// A neck's and an arm's curvature.
struct Bend {
  neck: f32,
  arm: f32,
};

// A point d metres along a tentacle bent so, and its heading there, in the tentacle's plane.
fn along(bend: Bend, d: f32) -> vec3f {
  if (d <= NECK) { return vec3f(arcAt(bend.neck, d), bend.neck * d); }
  let turn = bend.neck * NECK;
  return vec3f(arcAt(bend.neck, NECK) + turned(arcAt(bend.arm, d - NECK), turn), turn + bend.arm * (d - NECK));
}

// Where tentacle t plants on step number step: a rung ahead of where the body was when it let go.
fn plant(tentacle: u32, step: f32, stride: f32, bodyZ: f32, own: f32, seed: u32, params: Params) -> vec3f {
  let steps = round(PATH_PERIOD / stride);
  let wrapped = u32(step - floor(step / steps) * steps + 0.5);
  var z = (step - STEP_PHASE[tentacle] - own) * stride + params.lead + (chance(tentacle, wrapped, seed) - 0.5) * 0.4;
  z = round(z / RUNG) * RUNG;
  // The same rung from whichever side of the path's wrap the body is on.
  z = z - round((z - bodyZ) / PATH_PERIOD) * PATH_PERIOD;
  let theta = WALL_ANGLE[tentacle] + (chance(tentacle, wrapped, seed + 1u) - 0.5) * 0.45;
  let wall = pathFrame(z);
  // A hall's wall stands further off; the rung is on it all the same (whether the claw can reach it is the gait's business).
  return wall.origin + (wall.right * cos(theta) + wall.up * sin(theta)) * (params.bore * (1.0 + CHAMBER_SWELL * chamberAt(z)));
}

// ── The trail: what a tentacle does that holds nothing ──
// It streams back along the way the robot has come, as a squid's do: the bundle leaves the body
// in the arrangement the sockets have, draws in a little, lies along the tunnel behind (so it
// bends where the tunnel bent), squiggles more the further out, and only its ends stand apart.
// (The owner, 2026-10-05: "legs point straight away from it instead of going a bit to the back
// and then apart like a squid would … just the ends a bit spread out, the rest slightly
// squiggled but oriented backwards for the most part or rather along the velocity vector".)
// A shape, not a simulation: the kernel cannot read a neighbour, so there is no rope to solve (§T1585b).
struct Trail {
  z0: f32, // where along the tunnel its socket is
  across: vec2f, // the socket's direction off the body's axis, on the body's own right and up
  radius: f32, // how far off that axis the socket is, metres
  right: vec3f, // the body's right and up: the bundle starts on these and settles onto the tunnel's
  up: vec3f,
  offset: vec2f, // the body's place off the tunnel's axis: the bundle is drawn back onto the axis behind it
  flare: f32, // how far the ends stand apart at rest, metres
  swim: f32, // how much it is swimming, 0 to 1
  stroke: f32, // where the swimming beat is, 0 to 1
  adrift: f32, // how much the body is adrift, 0 to 1, and its own count
  own: f32,
  wave: f32, // the squiggle's size, metres
  phase: f32, // this tentacle's own count
  time: f32,
};

// How open the swimming beat has the tentacles, 0 to 1: flung open at the top of the beat, drawn
// in over the next third of it, drifting open again.
fn strokeOpen(stroke: f32) -> f32 {
  let at = stroke - floor(stroke);
  return select(smoothstep(0.34, 1.0, at), 1.0 - smoothstep(0.0, 0.34, at), at < 0.34);
}

// How far off the axis the trail runs s metres along, and how fast that changes.
fn trailRadius(t: Trail, s: f32) -> vec2f {
  // The beat reaches the ends late: what the body did a fifth of a bar ago, the tips do now. That lag is the drag.
  let open = t.swim * strokeOpen(t.stroke - 0.2 * s / LENGTH);
  let tip = t.flare + open * 0.85;
  let begins = LENGTH * mix(0.6, 0.3, open);
  let inward = clamp(s / 1.2, 0.0, 1.0);
  let apart = clamp((s - begins) / max(LENGTH - begins, 1e-3), 0.0, 1.0);
  let drawn = inward * inward * (3.0 - 2.0 * inward);
  let spread = apart * apart * (3.0 - 2.0 * apart);
  let radius = t.radius * (1.0 - 0.4 * drawn) + tip * spread * spread;
  let slope = -0.4 * t.radius * 6.0 * inward * (1.0 - inward) / 1.2 + tip * 2.0 * spread * 6.0 * apart * (1.0 - apart) / max(LENGTH - begins, 1e-3);
  return vec2f(radius, slope);
}

// A tentacle does not stretch: what it spends going outward it does not go back. The distance
// back along the axis after s metres of tentacle (a six-step sum; the squiggle takes a little more).
fn trailBack(t: Trail, s: f32) -> f32 {
  var back = 0.0;
  for (var i = 0u; i < 6u; i = i + 1u) {
    let slope = trailRadius(t, s * (f32(i) + 0.5) / 6.0).y;
    back = back + sqrt(max(1.0 - slope * slope, 0.04));
  }
  return back * s / 6.0 * 0.97;
}

fn trailShape(t: Trail, s: f32) -> vec3f {
  let tunnel = pathFrame(t.z0 - trailBack(t, s));
  let settle = 1.0 - exp(-s / 0.8);
  let right = normalize(mix(t.right, tunnel.right, settle));
  let up = normalize(mix(t.up, tunnel.up, settle));
  let around = right * t.across.x + up * t.across.y;
  let sideways = normalize(cross(around, tunnel.forward));
  let reach = s / LENGTH;
  // A long slow wave running out to the tip, growing as it goes: water, not a spring.
  let size = t.wave * (0.15 + 3.0 * reach * reach);
  let count = s * 1.7 - t.time * 1.25 + t.phase;
  let squiggle = (sideways * sin(count) + around * 0.6 * cos(count * 0.7 + 1.0)) * size;
  // A slow sway of the whole tail, a pendulum's: nothing at the body, most at the tip.
  let sway = sideways * sin(t.time * 0.45 + t.phase * 1.3) * 0.26 * reach * reach;
  // The tail goes where the body WENT: s metres back it is where the body had wandered to half a second
  // a metre ago. What else has the body off the axis (the tentacles that carry it) dies away behind it.
  let wandered = t.adrift * adriftAcross(t.time, t.own);
  let followed = t.adrift * adriftAcross(t.time - s * 0.5, t.own) + (t.offset - wandered) * exp(-s / 1.5);
  return tunnel.origin + tunnel.right * followed.x + tunnel.up * followed.y + around * trailRadius(t, s).x + squiggle + sway;
}

// How firmly tentacle t is told to take the wall. Crawl says how many do; WHICH ones moves
// round the body as it goes (one tentacle's turn every 9.6 m, which divides the path's length,
// so the set is the same either side of its wrap), so no tentacle holds for ever and none
// trails for ever. The hand-over is slow, most of a turn: a tentacle lets go and drifts back,
// or reaches forward and takes hold, over some three seconds. At Crawl 1 every one holds.
fn grabbing(tentacle: u32, crawl: f32, bodyZ: f32) -> f32 {
  let all = f32(TENTACLES);
  let centre = bodyZ / 9.6;
  let off = ENGAGE[tentacle] - centre;
  let apart = abs(off - all * round(off / all));
  let reach = clamp(crawl, 0.0, 1.0) * (all * 0.5 + 0.9);
  let held = clamp((reach - apart) / 0.9, 0.0, 1.0);
  // Quintic: it neither starts nor lands with a jolt.
  return held * held * held * (held * (held * 6.0 - 15.0) + 10.0);
}

// One tentacle's gait: how far through its step it is.
fn swingOf(tentacle: u32, bodyZ: f32, stride: f32, count: f32, duty: f32) -> f32 {
  let cycle = bodyZ / stride + STEP_PHASE[tentacle] + count;
  return smoothstep(0.0, 1.0, clamp((cycle - floor(cycle) - duty) / max(1.0 - duty, 1e-3), 0.0, 1.0));
}

// What carries the body: the tentacles that hold. Across the bore it hangs toward where they
// hold (x right, y up, as a share of the bore's radius); z is how many of the ten are holding.
fn carried(bodyZ: f32, stride: f32, count: f32, seed: u32, params: Params) -> vec3f {
  let tunnel = pathFrame(bodyZ);
  var toward = vec2f(0.0);
  var holding = 0.0;
  for (var t = 0u; t < TENTACLES; t = t + 1u) {
    let swing = swingOf(t, bodyZ, stride, count, params.duty);
    let hold = grabbing(t, params.crawl, bodyZ) * (1.0 - sin(swing * 3.14159265));
    let step = floor(bodyZ / stride + STEP_PHASE[t] + count);
    let held = mix(plant(t, step, stride, bodyZ, count, seed, params), plant(t, step + 1.0, stride, bodyZ, count, seed, params), swing) - tunnel.origin;
    let across = vec2f(dot(held, tunnel.right), dot(held, tunnel.up));
    toward = toward + hold * across / max(length(across), 1e-3);
    holding = holding + hold;
  }
  return vec3f(toward / max(holding, 1.0), holding);
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  q.slip = 0.0;
  q.charge = 0.0;
  q.seed = chance(ctx.index, PICK_FIRST, 7u);
  let robot = ctx.index / ROBOT_POINTS;
  if (robot >= ROBOTS) {
    q.kind = -1.0;
    return q;
  }
  let place = ctx.index % ROBOT_POINTS;
  let tentacle = place / PICK_COUNT;
  let station = PICK_FIRST + place % PICK_COUNT;
  let params = ctx.params;
  let offset = params.offset + ROBOT_OFFSET[robot];
  let swimming = swimAt(params.swim, params.travel + offset.z);
  // Where the gait counts from: the rungs it plants on are a matter of how far it has come.
  let bodyZ = robotZ(params.travel, offset, params.swim, params.stroke);
  let stride = PATH_PERIOD / round(PATH_PERIOD / max(params.stride, 0.5));
  let count = f32(robot) * 0.37 * params.variety;
  // A pack in unison plants on the same ribs; with variety each robot draws its own.
  let seed = 1u + u32(f32(robot) * params.variety + 0.5) * 16u;
  // The body is not on rails. Walking, the tentacles that hold carry it: it hangs toward
  // them and leans that way. SMOOTHLY (the owner, 2026-10-05: "too bobby in its sway … these
  // things move smooth not jerk"): what carries it is averaged over a whole stride, four
  // readings a quarter-stride apart, so no single step shows in the body, only where the
  // holding has been tending. No bob and no pulls. Swimming, nothing holds it and it is adrift.
  var hang = vec3f(0.0);
  for (var k = 0u; k < 4u; k = k + 1u) {
    hang = hang + carried(bodyZ - stride * 0.25 * f32(k), stride, count, seed, params) * 0.25;
  }
  let afoot = (1.0 - swimming) * params.carry * clamp(hang.z, 0.0, 1.0);
  let sway = vec3f(hang.xy * 0.55, 0.0) * afoot;
  let adrift = swimming * params.carry;
  let frameZ = bodyZ + adrift * adriftZ(ctx.absTime, offset);
  let body = robotFrame(frameZ, offset + sway, params.roll - hang.x * 0.18 * afoot, params.look + vec2f(hang.x * 0.08 * afoot, 0.0), ctx.absTime, adrift);
  if (PICK_BODY) {
    // The robot's own point: where its body is and how it is turned (the kit's robot frame: +Z forward, +Y up).
    q.position = body.origin;
    q.orient = quatFromFrame(body.right, body.up, body.forward);
    q.kind = 10.0;
    return q;
  }
  let socket = SOCKET[tentacle];
  let root = body.origin + body.right * socket.x + body.up * socket.y + body.forward * socket.z;
  let radial = normalize(body.right * socket.x + body.up * socket.y);

  // ── Walking: stance on one rib, then a swing to the next ──
  let step = floor(bodyZ / stride + STEP_PHASE[tentacle] + count);
  let swing = swingOf(tentacle, bodyZ, stride, count, params.duty);
  let rib = plant(tentacle, step, stride, bodyZ, count, seed, params);
  let next = plant(tentacle, step + 1.0, stride, bodyZ, count, seed, params);
  var walking = mix(rib, next, swing);
  let aloft = sin(swing * 3.14159265);
  walking = mix(walking, pathAt(walking.z), params.lift * aloft);

  let grab = grabbing(tentacle, params.crawl, bodyZ) * (1.0 - swimming);
  let leave = normalize(body.forward * -0.6 + radial * 0.8);

  // ── Trailing: the neck curls back into the wake (less with Flare), the arm sways, the plane rocks ──
  let wake = -body.forward;
  let toWake = normalize(wake - leave * dot(wake, leave));
  let side = cross(leave, toWake);
  let rock = sin(ctx.absTime * 0.6 + f32(tentacle) * 1.3) * 0.5;
  let loosePlane = toWake * cos(rock) + side * sin(rock);
  // Swimming opens and shuts them together: splayed wide at the top of the beat, streamlined after the snap.
  let open = select(smoothstep(0.25, 1.0, params.stroke), 1.0 - smoothstep(0.0, 0.25, params.stroke), params.stroke < 0.25);
  let splay = clamp(params.flare + swimming * (open * 1.1 - 0.15), -0.2, 1.2);
  let trailing = Bend(
    acos(clamp(dot(leave, wake), -1.0, 1.0)) * (1.0 - splay) / NECK,
    (sin(ctx.absTime * 0.9 + f32(tentacle) * 2.1) * 0.35 - swimming * open * 0.6) / ARM,
  );
  // Gesturing: the neck turns the other way, out and forward, and the arm curls and uncurls
  // on two slow counts of its own, so no two tentacles feel about in step. Swimming overrides it.
  let own = f32(tentacle) * 1.9 + f32(robot) * 0.7;
  let feeling = Bend(
    -(1.0 + 0.35 * sin(ctx.absTime * 0.7 + own)) / NECK,
    (0.9 * sin(ctx.absTime * 1.1 + own * 1.3) + 0.7 * sin(ctx.absTime * 0.43 + own * 0.6)) / ARM,
  );
  let reaching = clamp(params.gesture, 0.0, 1.0) * (1.0 - swimming);
  let loose = Bend(mix(trailing.neck, feeling.neck, reaching), mix(trailing.arm, feeling.arm, reaching));

  // ── Holding: the one arc from socket to claw, bowing the way the socket faces ──
  let span = walking - root;
  let far = max(length(span), 1e-4);
  let chord = span / far;
  let deployed = min(LENGTH, far / sinc(BOW_LIMIT));
  let half = halfTurn(min(far / deployed, 1.0));
  let lean = leave - chord * dot(leave, chord);
  let bow = select(toWake, normalize(lean), length(lean) > 1e-4);
  let holdLeave = chord * cos(half) + bow * sin(half);
  let holdPlane = chord * sin(half) - bow * cos(half);
  let holdBend = 2.0 * half / deployed;

  // Between the two the socket's direction, the plane and the curvatures all blend.
  let out = normalize(mix(leave, holdLeave, grab));
  let blended = mix(loosePlane, holdPlane, grab);
  let plane = normalize(blended - out * dot(blended, out));
  let bend = Bend(mix(loose.neck, holdBend, grab), mix(loose.arm, holdBend, grab));
  let run = mix(LENGTH, deployed, grab);

  // ── This joint's place along it ──
  let ring = station < RINGS;
  // Metres from the socket along what is deployed; under zero the joint is still stowed in the body.
  let d = select(HUB_DISTANCE, RING_START + f32(station) * RING_PITCH, ring) - (LENGTH - run);
  if (d < 0.0) {
    q.position = root;
    q.kind = -1.0;
    q.slip = 0.0;
    return q;
  }
  let here = along(bend, d);
  var at = root + out * here.x + plane * here.y;
  var tangent = out * cos(here.z) + plane * sin(here.z);
  var normal = plane * cos(here.z) - out * sin(here.z);
  // A tentacle that neither holds nor reaches trails: its place is the trail's, not an arc's.
  let loosely = (1.0 - grab) * (1.0 - reaching);
  if (loosely > 0.0) {
    let axis = pathFrame(frameZ);
    let off = body.origin - axis.origin;
    var trail: Trail;
    trail.z0 = frameZ + socket.z;
    trail.radius = max(length(socket.xy), 1e-3);
    trail.across = socket.xy / trail.radius;
    trail.right = body.right;
    trail.up = body.up;
    trail.offset = vec2f(dot(off, axis.right), dot(off, axis.up));
    // Swimming flings the ends wide at the top of the beat and draws them in after it (trailRadius).
    trail.flare = 0.18 + 0.7 * params.flare;
    trail.swim = swimming;
    trail.stroke = params.stroke;
    trail.adrift = adrift;
    trail.own = ownCount(offset);
    trail.wave = params.wave * 1.6 + 0.03;
    // Each robot of a pack squiggles on its own count, as far as Variety says (in unison they are one robot).
    trail.phase = f32(tentacle) * 1.7 + f32(robot) * 0.9 * params.variety;
    trail.time = ctx.absTime;
    let trailAt = root + trailShape(trail, d) - trailShape(trail, 0.0);
    let trailTangent = normalize(trailShape(trail, d + 0.04) - trailShape(trail, max(d - 0.04, 0.0)));
    let outward = body.right * trail.across.x + body.up * trail.across.y;
    at = mix(at, trailAt, loosely);
    tangent = normalize(mix(tangent, trailTangent, loosely));
    normal = mix(normal, outward, loosely);
    normal = normalize(normal - tangent * dot(normal, tangent));
  }
  let binormal = cross(tangent, normal);
  // A wave runs root to tip; it dies at both ends, and a planted tentacle carries less of it.
  let planted = grab * (1.0 - aloft);
  let ripple = d * 3.0 - ctx.absTime * params.waveRate + f32(tentacle) * 1.7;
  at = at + (normal * cos(ripple) + binormal * sin(ripple)) * (params.wave * sin(3.14159265 * d / run) * (1.0 - 0.6 * planted));
  // The kit's joint frame and the curve family's: +Z the tangent, +Y the normal, +X = normal × tangent.
  let frame = quatFromFrame(-binormal, normal, tangent);
  // ── What runs along the cores ──
  // A pulse leaves the body and runs to the claw at 9 metres a second, a hand's width long, fading as it goes.
  let crest = d - 9.0 * params.pulse;
  var charge = exp(-crest * crest / 0.12) * exp(-params.pulse * 1.2);
  // A level meter: a bright head as far out as the level says, each tentacle reading a little differently, and a
  // faint trail back to the body. (Lit all the way it was the row of red dashes again.)
  let reading = clamp(params.meter, 0.0, 1.0) * (0.75 + 0.5 * chance(tentacle, 3u, seed)) * LENGTH;
  charge = charge + (1.0 - smoothstep(reading - 0.15, reading, d)) * (0.05 + 0.75 * smoothstep(reading - 0.45, reading, d)) * select(0.0, 1.0, params.meter > 0.001);
  // Bands running out, one band's spacing a beat.
  let band = 0.5 + 0.5 * cos(6.2831853 * (d / LENGTH * params.bands - params.chasePhase + f32(tentacle) * 0.1));
  charge = charge + params.chase * pow(band, 8.0);
  // Single cores flashing, a new draw fourteen times a second.
  charge = charge + params.spark * select(0.0, 1.0, chance(ctx.index, u32(ctx.absTime * 14.0), seed + 5u) > 0.93);
  q.charge = charge;
  q.along = clamp(d / LENGTH, 0.0, 1.0);
  // How far the claw's mouth is from where the gait wants it: zero while its rung is in reach.
  let mouth = along(bend, run);
  q.slip = grab * distance(root + out * mouth.x + plane * mouth.y, walking);

  if (ring) {
    q.position = at;
    q.orient = frame;
    q.kind = 0.0;
    q.matte = 1.0;
    return q;
  }
  if (station == RINGS) {
    q.position = at;
    q.orient = frame;
    q.kind = 1.0;
    return q;
  }
  // ── The claw: each phalanx on its carrier, turned about its hinge ──
  let which = station - RINGS - 1u;
  let knuckle = which - which % 2u;
  // A planted claw grips; one that holds nothing hangs open, shuts on Snap, and works idly while it feels about.
  let idle = clamp(params.snap + reaching * (0.5 + 0.5 * sin(ctx.absTime * 2.6 + own)) * 0.6, 0.0, 1.0);
  let closed = mix(idle * (1.0 - grab), params.grip, planted);
  let knuckleFrame = quatMul(quatMul(frame, quatAxisAngle(PHALANX_AXIS[knuckle], mix(PHALANX_RANGE[knuckle].x, PHALANX_RANGE[knuckle].y, closed))), PHALANX_REST[knuckle]);
  let knuckleAt = at + quatRotate(frame, PHALANX_JOINT[knuckle]);
  var jointFrame = knuckleFrame;
  var jointAt = knuckleAt;
  if (which % 2u == 1u) {
    jointFrame = quatMul(quatMul(knuckleFrame, quatAxisAngle(PHALANX_AXIS[which], mix(PHALANX_RANGE[which].x, PHALANX_RANGE[which].y, closed))), PHALANX_REST[which]);
    jointAt = knuckleAt + quatRotate(knuckleFrame, PHALANX_JOINT[which]);
  }
  q.position = jointAt;
  q.orient = jointFrame;
  q.kind = 2.0 + f32(which);
  return q;
}

parameters.source:
// @use surface-detail
struct Params {
  wet: f32, // @default 0.4  How much water still runs: the tracks down the wall and the pools on the deck.
  grime: f32, // @default 0.85  Rust, soot and silt.
  lamp: f32, // @default 14  Radiance of the lamp plates in the crown.
};

// Chambers (src/projects/sentinel-bot/path.ts, CHAMBERS): 0 in the bore, 1 across a hall's middle.
const CHAMBER_SWELL: f32 = 0.9;
fn chamberAt(z: f32) -> f32 {
  let along = z - 96.0 * floor(z / 96.0);
  return 1.0 - smoothstep(6.0, 13.0, abs(along - 48.0));
}
const LAMP: f32 = 12.80000;
const LAMP_GAIN = array<f32, 15>(1.00, 0.20, 1.00, 1.00, 0.06, 0.40, 1.00, 1.00, 0.20, 0.06, 0.40, 1.00, 1.00, 0.20, 0.40);
// The light of the lamp at a station (tunnel.ts, LAMP_TONES and LAMP_GAINS): cold in the bore, sodium in a hall,
// every fifteenth an alarm; and of every run of fifteen, some are dead and some failing.
fn lampTone(station: f32) -> vec3f {
  let turn = station - 15.0 * floor(station / 15.0);
  if (abs(turn - 7.0) < 0.5) { return vec3f(1.0000, 0.1000, 0.0600); }
  let gain = LAMP_GAIN[u32(clamp(turn + 0.5, 0.0, 14.5))];
  return mix(vec3f(0.6200, 0.8400, 1.0000), vec3f(1.0000, 0.6200, 0.2800), step(0.5, chamberAt((station + 0.5) * LAMP))) * gain;
}


fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
  var o = surfaceDefaults(s);
  let what = s.tint.r;
  let own = s.tint.g;
  let around = s.tint.b;
  let along = s.tint.a;
  // 0 at the crown, 1 at the bottom of the bore.
  let low = abs(around - 0.5) * 2.0;
  let stain = detailFbm(s.world * 0.55, 4, s.footprint);
  let spall = detailFbm(s.world * 4.3, 4, s.footprint);
  let grit = detailFbm(s.world * 31.0, 3, s.footprint);
  // Water comes down the wall: tracks a hand wide that run the long way round it.
  let track = detailFbm(vec3f(along * 7.0, around * 2.2, 3.0), 3, s.footprint).value;
  let run = smoothstep(0.6, 0.72, track) * (0.35 + 0.65 * low);
  let dirt = p.grime * smoothstep(0.3, 0.72, stain.value);
  let pit = smoothstep(0.52, 0.8, spall.value);

  // The liner: concrete segments, each cast on its own day.
  var albedo = mix(vec3f(0.03, 0.03, 0.032), vec3f(0.16, 0.135, 0.105), 0.25 + 0.75 * own) * (0.55 + 0.6 * stain.value);
  var rough = 0.9;
  var metal = 0.0;
  var relief = 0.14;
  if (what > 2.5) {
    // The deck: plate steel under silt.
    albedo = mix(vec3f(0.04, 0.038, 0.036), vec3f(0.09, 0.066, 0.04), dirt);
    rough = 0.78;
    metal = 0.5 * (1.0 - dirt);
    relief = 0.09;
  } else if (what > 1.5) {
    // Pipes and cable runs: ochre, oxide green or red lead, flaking to the iron.
    let paint = mix(mix(vec3f(0.13, 0.105, 0.03), vec3f(0.03, 0.07, 0.052), step(0.34, own)), vec3f(0.12, 0.03, 0.02), step(0.67, own));
    albedo = mix(paint, vec3f(0.06, 0.05, 0.046), pit);
    rough = 0.66;
    metal = 0.55 * pit;
    relief = 0.06;
  } else if (what > 0.5) {
    // Ribs: iron, mostly rust.
    albedo = mix(vec3f(0.05, 0.048, 0.05), vec3f(0.16, 0.066, 0.026), 0.35 + 0.65 * smoothstep(0.25, 0.7, spall.value) * p.grime);
    rough = 0.74;
    metal = 0.6 * (1.0 - pit);
    relief = 0.08;
  }
  // Rust and soot: brown where water has carried it, black where nothing has washed it.
  albedo = mix(albedo, vec3f(0.15, 0.062, 0.024), run * p.grime * 0.75);
  albedo = mix(albedo, vec3f(0.014, 0.014, 0.015), dirt * 0.55);
  // Silt at the foot of the wall.
  let silt = p.grime * smoothstep(0.62, 0.86, low + (stain.value - 0.5) * 0.25) * step(what, 2.5);
  albedo = mix(albedo, vec3f(0.07, 0.052, 0.034), silt * 0.8);
  // What still shines: the running tracks, and pools where the deck dips.
  let pool = step(2.5, what) * smoothstep(0.5, 0.62, stain.value);
  let film = clamp(p.wet * max(run * 0.9, pool), 0.0, 1.0);
  rough = mix(rough + 0.08 * (grit.value - 0.5), 0.12, film);
  albedo = albedo * (1.0 - 0.35 * film);

  o.albedo = vec4f(albedo, 1.0);
  o.roughness = clamp(rough, 0.06, 1.0);
  o.metallic = metal * (1.0 - film);
  // Pitted and spalled where dry; water lies flat.
  // (Fine grit in the normal made every lit metre of wall sparkle: it roughens, it does not glint.)
  o.normal = detailBump(s.normal, stain.gradient * 0.55 * 0.4 + spall.gradient * 4.3 * 0.42 + grit.gradient * 31.0 * 0.025, relief * (1.0 - 0.85 * film));

  // A lamp plate in the crown at every lamp station; each has its own steadiness.
  let station = floor(along / LAMP);
  let onPlate = (1.0 - smoothstep(0.3, 0.36, abs(along - (station + 0.5) * LAMP))) * (1.0 - smoothstep(0.012, 0.016, abs(around - 0.5)));
  let nerve = fract(sin(station * 12.9898) * 43758.5453);
  let flicker = 1.0 - step(0.82, nerve) * step(0.6, fract(sin(floor(s.absTime * 11.0) * 78.233 + station) * 43758.5453)) * 0.8;
  o.emissive = o.emissive + lampTone(station) * p.lamp * onPlate * flicker;
  return o;
}

// @use surface-detail
struct Params {
  lamp0: vec3f, // @default [0, 2.25, -19.2]  Where the lamp -2 stations on from the robot's own hangs.
  lamp1: vec3f, // @default [0, 2.25, -6.4]  Where the lamp -1 stations on from the robot's own hangs.
  lamp2: vec3f, // @default [0, 2.25, 6.4]  Where the lamp 0 stations on from the robot's own hangs.
  lamp3: vec3f, // @default [0, 2.25, 19.2]  Where the lamp 1 stations on from the robot's own hangs.
  lamp4: vec3f, // @default [0, 2.25, 32.0]  Where the lamp 2 stations on from the robot's own hangs.
  station: f32, // @default 37  The station the robot is under: which lamp is which tone.
  lamps: f32, // @default 6  Radiance of a lamp plate, as the steel reflects it.
  pool: f32, // @default 0.05  Radiance of the lit liner round a plate, as a share of the plate's.
  deck: f32, // @default 0.2  How much of all that the wet deck throws back up.
  gloss: f32, // @default 0.42  Roughness of the shell where nothing has worn or soiled it.
  steel: f32, // @default 0.3  How much of what it faces the shell throws back: 0.04 is enamel, 0.6 bare steel.
  wear: f32, // @default 0.8  How old it is: rubbed edges, rust, dust. 0 is as the kit left the works.
  hueFrom: f32, // @default 0  The lights' colour range starts at this hue, 0 to 1 round the wheel (0 red).
  hueTo: f32, // @default 0.03  …and ends at this one.
  spread: f32, // @default 0.6  How much of the range the lights are spread over: 0 all one colour, 1 the lenses (and the length of a tentacle) cover it all.
  shift: f32, // @default 0  Moves every light along the range, 0 to 1. Drive it from a level.
  eyeGlow: f32, // @default 9  Radiance of the eye lenses.
  eyeHits: f32, // @default 0  How much the lenses answer the drums instead of burning steadily: a third of them each to kick, snare and hat.
  kick: f32, // @default 0  The kick, 0 to 1 as it decays.
  snare: f32, // @default 0  The snare.
  hat: f32, // @default 0  The hat.
  eyeSweep: f32, // @default 0  How much a band of light crossing the face takes over from the steady glow.
  sweepPhase: f32, // @default 0  Where that band is: it crosses once for each whole number. Drive it from the beat.
  coreGlow: f32, // @default 0.07  Radiance of a tentacle's light segments at rest: low, so the segmenting shows and no more.
  pulseGlow: f32, // @default 1.6  Radiance of a segment fully charged.
};

// What each drawn piece brings of its own: the rig's point attributes of the same names (rig.ts).
struct Instance {
  charge: f32, // @default 0  How lit this piece's light segment is by what runs along the tentacle: 0 at rest, 1 fully.
  seed: f32, // @default 0  Which piece it is, 0 to 1: its wear is its own.
  along: f32, // @default 0  How far along its tentacle it is, 0 at the body to 1 at the claw: its place in the colour range.
  matte: f32, // @default 0  1 on a tentacle's rings: the dark segments between its lights.
};

fn hueColour(hue: f32) -> vec3f {
  let wheel = clamp(abs(fract(vec3f(hue) + vec3f(0.000000, 0.666667, 0.333333)) * 6.0 - 3.0) - 1.0, vec3f(0.0), vec3f(1.0));
  return wheel * 0.96 + 0.04;
}

// The colour of the light at a place (0 to 1) in the range.
fn lightColour(place: f32, p: Params) -> vec3f {
  return hueColour(mix(p.hueFrom, p.hueTo, clamp(place * p.spread + p.shift, 0.0, 1.0)));
}

// Chambers (src/projects/sentinel-bot/path.ts, CHAMBERS): 0 in the bore, 1 across a hall's middle.
const CHAMBER_SWELL: f32 = 0.9;
fn chamberAt(z: f32) -> f32 {
  let along = z - 96.0 * floor(z / 96.0);
  return 1.0 - smoothstep(6.0, 13.0, abs(along - 48.0));
}
const LAMP: f32 = 12.80000;
const LAMP_GAIN = array<f32, 15>(1.00, 0.20, 1.00, 1.00, 0.06, 0.40, 1.00, 1.00, 0.20, 0.06, 0.40, 1.00, 1.00, 0.20, 0.40);
// The light of the lamp at a station (tunnel.ts, LAMP_TONES and LAMP_GAINS): cold in the bore, sodium in a hall,
// every fifteenth an alarm; and of every run of fifteen, some are dead and some failing.
fn lampTone(station: f32) -> vec3f {
  let turn = station - 15.0 * floor(station / 15.0);
  if (abs(turn - 7.0) < 0.5) { return vec3f(1.0000, 0.1000, 0.0600); }
  let gain = LAMP_GAIN[u32(clamp(turn + 0.5, 0.0, 14.5))];
  return mix(vec3f(0.6200, 0.8400, 1.0000), vec3f(1.0000, 0.6200, 0.2800), step(0.5, chamberAt((station + 0.5) * LAMP))) * gain;
}

// What a ray going up (d.y > 0) from `here` sees of the lamp of `station` hanging at `lampAt`, in the level
// plane it hangs in. `pool` is the lit liner round the plate as a share of the plate's radiance; `soft`
// widens the plate's edge, metres (a rough mirror).
fn lampSeen(d: vec3f, here: vec3f, lampAt: vec3f, station: f32, pool: f32, soft: f32) -> vec3f {
  let lamp = lampAt - here;
  // The tunnel climbs and falls: a lamp below this height is round a bend of it.
  if (lamp.y < 0.3) { return vec3f(0.0); }
  let hit = d * (lamp.y / d.y);
  let across = hit.x - lamp.x;
  let along = hit.z - lamp.z;
  let plate = (1.0 - smoothstep(0.2, 0.26 + soft, abs(across))) * (1.0 - smoothstep(0.3, 0.36 + soft, abs(along)));
  let lit = exp(-(across * across + along * along) / 3.0) * pool;
  // Air between: a far lamp is a dim one.
  return lampTone(station) * (plate + lit) * exp(-length(hit) * 0.035);
}

fn surface(s: SurfaceIn, p: Params) -> SurfaceOut {
  var o = surfaceDefaults(s);
  let role = s.attr.z;
  var albedo = vec3f(p.steel * 0.92, p.steel * 0.96, p.steel * 1.05);
  var rough = p.gloss;
  var metal = 1.0;
  // Whether it ages, and whether it is a mirror to the lamps.
  var ages = 1.0;
  var mirrors = 1.0;
  if (role > 0.9) {
    // A lens: black glass over a lamp, brightest where it faces the viewer.
    let facing = max(dot(normalize(s.eye - s.world), s.normal), 0.0);
    // Each lens has a nerve of its own: the eyes are a hand's breadth apart in the robot's frame, so a coarse cell of it names one.
    let lens = floor(s.local * 7.0);
    let nerve = fract(sin(dot(lens, vec3f(12.9898, 78.233, 37.719))) * 43758.5453);
    let life = 0.8 + 0.2 * sin(s.absTime * (1.5 + nerve * 4.0) + nerve * 40.0);
    albedo = vec3f(0.006, 0.006, 0.006);
    rough = 0.08;
    metal = 0.0;
    // The drums: a third of the lenses each to kick, snare and hat. With Eye Hits up a lens sits low and flashes on its own drum.
    let drum = select(select(p.hat, p.snare, nerve < 0.667), p.kick, nerve < 0.333);
    let struck = mix(1.0, 0.25 + 2.6 * drum, clamp(p.eyeHits, 0.0, 1.0));
    // A band of light crossing the face from one side to the other, once for each whole number of the phase.
    let band = pow(0.5 + 0.5 * cos(6.2831853 * (s.local.x * 0.9 - p.sweepPhase)), 3.0);
    let swept = mix(1.0, 0.2 + 2.4 * band, clamp(p.eyeSweep, 0.0, 1.0));
    o.emissive = lightColour(nerve, p) * p.eyeGlow * (0.35 + 0.65 * facing * facing) * life * struck * swept;
    ages = 0.0;
    mirrors = 0.0;
  } else if (role > 0.7) {
    // The spine between the rings is the tentacle's light: a segment of it shows between every two
    // rings, so a tentacle is lit, dark, lit, dark all the way down (the owner, 2026-10-05: that
    // segmenting is the look). Lit from inside by what runs along the tentacle, over a low glow at
    // rest. Not a mirror: as one, every segment found a lamp whatever the tentacle was doing.
    albedo = vec3f(0.022, 0.02, 0.02);
    rough = 0.72;
    metal = 0.2;
    o.emissive = lightColour(s.instance.along, p) * (p.coreGlow + p.pulseGlow * s.instance.charge);
    ages = 0.3;
    mirrors = 0.0;
  } else if (role > 0.5) {
    // Red lead paint.
    albedo = vec3f(0.11, 0.012, 0.009);
    rough = 0.5;
    metal = 0.25;
  } else if (role > 0.3) {
    // Brass, long tarnished.
    albedo = vec3f(0.3, 0.2, 0.08);
    rough = 0.45;
  } else if (role > 0.1) {
    // Bright steel that has not been bright for years.
    albedo = vec3f(0.34, 0.345, 0.36);
    rough = 0.36;
  }

  // A tentacle's rings are the DARK segments between its lights, and must stay dark from every
  // angle (the owner: "the not lit up segments were taking on too much light color so they did
  // not appear as a segment"). As polished steel they mirrored the light beside them; they are
  // matt black instead, and show no lamp.
  if (role <= 0.1 && s.instance.matte > 0.5) {
    albedo = vec3f(0.012, 0.012, 0.013);
    rough = 0.88;
    metal = 0.0;
    ages = 0.25;
    mirrors = 0.0;
  }

  // ── Age ──
  let wear = p.wear * ages;
  var pitted = s.normal;
  if (wear > 0.0) {
    let skin = s.local + vec3f(17.0, 31.0, 7.0) * s.instance.seed;
    let blotch = detailFbm(skin * 2.6, 4, s.footprint).value;
    let wet = detailFbm(skin * 1.4 + vec3f(41.0, 13.0, 29.0), 3, s.footprint).value;
    let grain = detailFbm(skin * 48.0, 3, s.footprint);
    // Scores and scratches: long thin marks the way things have dragged along it, each a hair wide.
    let score = detailFbm(vec3f(skin.x * 55.0, skin.y * 55.0, skin.z * 2.5) + vec3f(9.0), 3, s.footprint).value;
    let scratched = wear * smoothstep(0.7, 0.76, score);
    // Edges and raised detail, rubbed through to the metal.
    let rubbed = clamp(wear * detailEdgeWear(s.curvature, 18.0, grain.value) + scratched * 0.85, 0.0, 1.0);
    albedo = mix(albedo, vec3f(0.55, 0.53, 0.5), rubbed * 0.8);
    rough = mix(rough, 0.3, rubbed * 0.7);
    metal = mix(metal, 1.0, rubbed);
    // Rust where it has stood wet, pitted.
    let rust = wear * smoothstep(0.46, 0.7, wet) * (0.4 + 0.6 * grain.value) * (1.0 - rubbed);
    albedo = mix(albedo, vec3f(0.17, 0.062, 0.022), rust);
    rough = mix(rough, 0.9, rust);
    metal = mix(metal, 0.0, rust);
    // Soot and oil baked on, in patches: darker and duller, still metal underneath.
    let soot = wear * smoothstep(0.38, 0.62, blotch) * (1.0 - rubbed);
    albedo = albedo * (1.0 - 0.6 * soot);
    rough = mix(rough, 0.78, soot * 0.7);
    // Dust lying on what faces up.
    let dust = wear * smoothstep(0.5, 0.75, 1.0 - blotch) * max(s.normal.y, 0.0) * (1.0 - rubbed);
    albedo = mix(albedo, vec3f(0.05, 0.045, 0.038), dust * 0.8);
    rough = mix(rough, 0.96, dust * 0.8);
    metal = mix(metal, 0.0, dust * 0.8);
    // And no patch of it quite as smooth as the next; pitted all over.
    rough = rough + wear * (grain.value - 0.5) * 0.3;
    pitted = detailBump(s.normal, grain.gradient * 48.0, 0.0035 * wear);
  }
  o.normal = pitted;
  o.albedo = vec4f(albedo, 1.0);
  o.roughness = clamp(rough, 0.05, 1.0);
  o.metallic = metal;

  // A mirror shows what is along its mirror direction: the lamps overhead, and their smear in the wet deck
  // below (tunnel.ts). Metal only, and hardly at all once it is rough.
  let view = normalize(s.world - s.eye);
  let mirror = reflect(view, s.normal);
  let soft = o.roughness * 0.6;
  // Looking down, it is the deck's own mirror image of the same lamps, dimmer.
  let up = vec3f(mirror.x, max(abs(mirror.y), 0.02), mirror.z);
  var seen = vec3f(0.0);
  seen = seen + lampSeen(up, s.world, p.lamp0, p.station + -2.0, p.pool, soft);
  seen = seen + lampSeen(up, s.world, p.lamp1, p.station + -1.0, p.pool, soft);
  seen = seen + lampSeen(up, s.world, p.lamp2, p.station + 0.0, p.pool, soft);
  seen = seen + lampSeen(up, s.world, p.lamp3, p.station + 1.0, p.pool, soft);
  seen = seen + lampSeen(up, s.world, p.lamp4, p.station + 2.0, p.pool, soft);
  seen = seen * select(p.deck, 1.0, mirror.y > 0.0);
  // Schlick: at a grazing angle any metal is a full mirror.
  let graze = pow(1.0 - max(dot(-view, s.normal), 0.0), 5.0);
  let polish = (1.0 - o.roughness) * (1.0 - o.roughness);
  o.emissive = o.emissive + seen * p.lamps * mix(o.albedo.rgb, vec3f(1.0), graze) * o.metallic * polish * mirrors;
  return o;
}

struct Params {
  clampLuma: f32, // @default 0  Above 0: the first level's firefly clamp (Karis average weight).
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;

fn tap(uv: vec2f) -> vec3f {
  return textureSampleLevel(inputTexture, inputSampler, uv, 0.0).rgb;
}

fn karis(c: vec3f) -> f32 {
  return select(1.0, 1.0 / (1.0 + dot(c, vec3f(0.2126, 0.7152, 0.0722))), params.clampLuma > 0.0);
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let t = 1.0 / vec2f(textureDimensions(inputTexture));
  let a = tap(uv + t * vec2f(-2.0, -2.0)); let b = tap(uv + t * vec2f(0.0, -2.0)); let c = tap(uv + t * vec2f(2.0, -2.0));
  let d = tap(uv + t * vec2f(-2.0, 0.0));  let e = tap(uv);                          let f = tap(uv + t * vec2f(2.0, 0.0));
  let g = tap(uv + t * vec2f(-2.0, 2.0));  let h = tap(uv + t * vec2f(0.0, 2.0));  let i = tap(uv + t * vec2f(2.0, 2.0));
  let j = tap(uv + t * vec2f(-1.0, -1.0)); let k = tap(uv + t * vec2f(1.0, -1.0));
  let l = tap(uv + t * vec2f(-1.0, 1.0));  let m = tap(uv + t * vec2f(1.0, 1.0));
  // Five boxes: the centre one weighted 0.5, the four corner ones 0.125 each.
  let b0 = (j + k + l + m) * 0.25;
  let b1 = (a + b + d + e) * 0.25;
  let b2 = (b + c + e + f) * 0.25;
  let b3 = (d + e + g + h) * 0.25;
  let b4 = (e + f + h + i) * 0.25;
  let w0 = 0.5 * karis(b0);
  let w1 = 0.125 * karis(b1); let w2 = 0.125 * karis(b2); let w3 = 0.125 * karis(b3); let w4 = 0.125 * karis(b4);
  let sum = (b0 * w0 + b1 * w1 + b2 * w2 + b3 * w3 + b4 * w4) / max(w0 + w1 + w2 + w3 + w4, 1e-6);
  return vec4f(sum, 1.0);
}

