// Chambers (src/projects/sentinel-bot/path.ts, CHAMBERS): 0 in the bore, 1 across a hall's middle.
const CHAMBER_SWELL: f32 = 0.9;
fn chamberAt(z: f32) -> f32 {
  let along = z - 96.0 * floor(z / 96.0);
  return 1.0 - smoothstep(6.0, 13.0, abs(along - 48.0));
}
const LAMP: f32 = 12.80000;
const LAMP_GAIN = array<f32, 15>(1.00, 0.20, 1.00, 1.00, 0.06, 0.40, 1.00, 1.00, 0.20, 0.06, 0.40, 1.00, 1.00, 0.20, 0.40);
// The light of the lamp at a station (tunnel.ts, LAMP_TONES and LAMP_GAINS): cold in the bore, sodium in a hall,
// every fifteenth an alarm; and of every run of fifteen, some are dead and some failing.
fn lampTone(station: f32) -> vec3f {
  let turn = station - 15.0 * floor(station / 15.0);
  if (abs(turn - 7.0) < 0.5) { return vec3f(1.0000, 0.1000, 0.0600); }
  let gain = LAMP_GAIN[u32(clamp(turn + 0.5, 0.0, 14.5))];
  return mix(vec3f(0.6200, 0.8400, 1.0000), vec3f(1.0000, 0.6200, 0.2800), step(0.5, chamberAt((station + 0.5) * LAMP))) * gain;
}

// How much of a point light at `light` the air along a ray throws back, per unit of the light and of the air's
// own share: the integral of 1/d² from the lens out to `reach` metres, dimmed by the air it then crosses.
fn airlight(origin: vec3f, ray: vec3f, reach: f32, light: vec3f) -> f32 {
  let q = origin - light;
  let b = dot(ray, q);
  // No nearer than a lamp is wide: a ray through the lamp itself is a bright core, not infinity.
  let c = sqrt(max(dot(q, q) - b * b, 0.03));
  let nearest = clamp(-b, 0.0, reach);
  return (atan((reach + b) / c) - atan(b / c)) / c * exp(-nearest * params.density);
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let lit = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let view = makeView();
  let ray = rayAt(view, uv);
  let z = viewDepth(uv);
  // Nothing drawn here: the tunnel's own dark, all haze.
  let reach = select(z / max(dot(ray, view.forward), 1e-4), params.far, z < 0.0);
  let clear = exp(-reach * params.density);
  var air = params.eyeColor * params.eyes * airlight(params.eye, ray, reach, params.eyesAt);
  air = air + lampTone(params.station + -2.0) * params.lamp * airlight(params.eye, ray, reach, params.lamp0);
  air = air + lampTone(params.station + -1.0) * params.lamp * airlight(params.eye, ray, reach, params.lamp1);
  air = air + lampTone(params.station + 0.0) * params.lamp * airlight(params.eye, ray, reach, params.lamp2);
  air = air + lampTone(params.station + 1.0) * params.lamp * airlight(params.eye, ray, reach, params.lamp3);
  air = air + lampTone(params.station + 2.0) * params.lamp * airlight(params.eye, ray, reach, params.lamp4);
  return vec4f(mix(params.color, lit.rgb, clear) + air * params.glow, lit.a);
}

struct Params {
  eye: vec3f, // @default 0  Camera position (drive from the camera).
  aim: vec3f, // @default 0  Camera look-at (drive from the camera).
  fov: f32, // @default 50  Camera vertical field of view, degrees.
  far: f32, // @default 400  Camera far plane (depth arrives as distance ÷ far).
  roll: f32, // @default 0  Camera roll, degrees (drive from the camera).
  radius: f32, // @default 1.2  World radius of the occlusion search, metres.
  strength: f32, // @default 0.75  How much of the occlusion darkens the frame.
  power: f32, // @default 1.4  Contrast of the occlusion.
